def read_params(path):
    """Read parameters from file, so that it's readable by write_params.

    Uses INI file format.
    """
    with open(path, 'r') as f:
        lines = f.readlines()
    args = []
    dicts = {}
    for line in lines:
        line = line.strip()
        if line == '':
            continue
        if line[0] == '#':
            continue
        if line[0] == '[' and line[-1] == ']':
            continue
        if line.find('=') == -1:
            args.append(line)
        else:
            key, value = line.split('=')
            dicts[key] = value
    return args, dicts


